  function handleDragStart(ev){const el=ev.target.closest?.('[data-workos-drag-task]');if(!el)return false;local.dragTaskId=el.dataset.workosDragTask;local.dragSourceDate=el.closest('[data-workos-drop-date]')?.dataset.workosDropDate||'';ev.dataTransfer?.setData('text/plain',local.dragTaskId);if(ev.dataTransfer)ev.dataTransfer.effectAllowed='move';el.classList.add('dragging');return true;}
  function handleDragEnd(ev){ev.target.closest?.('[data-workos-drag-task]')?.classList.remove('dragging');document.querySelectorAll('.workos-drop-active').forEach(x=>x.classList.remove('workos-drop-active'));local.dragTaskId=null;return true;}
  function handleDragOver(ev){const zone=ev.target.closest?.('[data-workos-drop-date]');if(!zone||!local.dragTaskId)return false;ev.preventDefault();if(ev.dataTransfer)ev.dataTransfer.dropEffect='move';document.querySelectorAll('.workos-drop-active').forEach(x=>x!==zone&&x.classList.remove('workos-drop-active'));zone.classList.add('workos-drop-active');return true;}
  async function handleDrop(ev){const zone=ev.target.closest?.('[data-workos-drop-date]');const id=local.dragTaskId||ev.dataTransfer?.getData('text/plain');if(!zone||!id)return false;ev.preventDefault();zone.classList.remove('workos-drop-active');zone.classList.add('workos-calendar-updating');const progress=document.createElement('span');progress.className='workos-calendar-update-state';progress.setAttribute('role','status');progress.textContent=L('جارٍ تحديث الموعد…','Updating date…');zone.append(progress);try{const detail=await api.rpc('work_task_detail',{p_task_id:id}),t=detail?.task;if(!t||!detail?.capabilities?.edit)throw new Error(L('لا تملك صلاحية إعادة جدولة هذا العمل.','You cannot reschedule this work item.'));const targetDate=zone.dataset.workosDropDate,hour=zone.dataset.workosDropHour!==undefined?Number(zone.dataset.workosDropHour):null;const base=t.start_at?new Date(t.start_at):t.due_at?new Date(t.due_at):new Date();const due=t.due_at?new Date(t.due_at):null,start=t.start_at?new Date(t.start_at):null;const duration=start&&due?due-start:0;const [y,m,d]=targetDate.split('-').map(Number);const moved=new Date(base);moved.setFullYear(y,m-1,d);if(hour!==null)moved.setHours(hour,0,0,0);let nextStart=start?new Date(moved):null,nextDue=due?new Date(moved):null;if(start&&due){nextStart=new Date(moved);nextDue=new Date(nextStart.getTime()+duration);}await api.rpc('save_work_item',{p_payload:{id:t.id,company_id:t.company_id,start_at:nextStart?nextStart.toISOString():null,due_at:nextDue?nextDue.toISOString():null,expected_lock_version:Number(t.lock_version||1)}});await Promise.all([loadCalendar(false),loadCockpit(false),reloadDelivery()]);render();toast('success',L('تمت إعادة الجدولة','Work rescheduled'),formatDate(nextDue||nextStart));}catch(err){formError(err,L('تعذر إعادة الجدولة','Could not reschedule work'));}finally{progress.remove();zone.classList.remove('workos-calendar-updating');local.dragTaskId=null;}return true;}

  async function exportActivity(){
    try{
      const f={search:local.activity.search,action:local.activity.action,actor_id:local.activity.actor_id,from:local.activity.from?new Date(`${local.activity.from}T00:00:00`).toISOString():'',to:local.activity.to?new Date(`${local.activity.to}T23:59:59`).toISOString():''};
      const rows=[];let offset=0,hasMore=true;const ceiling=10000;
      while(hasMore&&rows.length<ceiling){const result=await api.rpc('work_activity_feed',{p_company_id:state.companyId,p_mode:local.activity.mode,p_filters:f,p_limit:200,p_offset:offset});rows.push(...arr(result.items));hasMore=Boolean(result.has_more);offset+=Number(result.limit||200);}
      const q=v=>`"${String(v??'').replaceAll('"','""')}"`;const csv=['id,created_at,actor,action,entity_type,entity_title,metadata',...rows.map(r=>[r.id,r.created_at,r.actor_name,r.action,r.entity_type,r.entity_title,JSON.stringify(r.metadata||{})].map(q).join(','))].join('\n');const blob=new Blob([`\uFEFF${csv}`],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`optimum-activity-${dateKey(new Date())}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);if(hasMore)toast('warning',L('تم تصدير أول 10,000 حدث','Exported the first 10,000 events'),L('استخدم نطاق تاريخ أضيق لتصدير بقية السجل.','Use a narrower date range to export the remaining ledger.'));
    }catch(err){formError(err,L('تعذر تصدير سجل النشاط','Could not export activity'));}
  }

  async function focusContext({projectId='',siteId='',folderId=''}={}){local.workspaceView='cockpit';local.simpleView='all';local.context={project_id:projectId||'',site_id:siteId||'',folder_id:folderId||''};local.task.project_id=projectId||'all';local.task.scope=allowed('tasks.view_all','tasks.manage')?'team':'my';local.task.status='active';local.task.task_type='all';local.task.risk='all';local.task.due='all';local.task.page=0;await loadTasks(0,false);syncLegacyState();replaceRoute('tasks');render();}
  async function focusProject(projectId){return focusContext({projectId});}

  function commandQuickActions(){const actions=[];if(can('tasks.create'))actions.push(['new-task','checkSquare',L('مهمة جديدة','New task')]);if(can('tasks.view'))actions.push(['workos-go-calendar','calendar',L('التقويم','Calendar')]);if(allowed('tasks.manage_templates','tasks.manage_automations','tasks.manage'))actions.push(['workos-admin','wand',L('إعدادات المهام','Task settings')]);return `<div class="orgos-command-actions workos-command-actions">${actions.map(([a,ic,label])=>`<button class="command-card" data-action="${a}">${icon(ic,17)}<span>${e(label)}</span></button>`).join('')}</div>`;}
  async function syncRemote(){if(!state.companyId||document.visibilityState==='hidden')return false;try{const rows=await api.rpc('work_runtime_revision',{p_company_id:state.companyId});const rev=Array.isArray(rows)?rows[0]:rows;if(!rev)return false;if(local.runtime&&Number(rev.revision)!==Number(local.runtime.revision)){local.runtime=rev;await load();render();toast('info',L('تم تحديث المهام تلقائيًا','Tasks updated automatically'),L('تم تطبيق تغيير وصل من جلسة أخرى.','A change from another session was applied.'));return true;}local.runtime=rev;return false;}catch{return false;}}

  return {load,page,calendarPage,activityPage,commandQuickActions,handleAction,handleChange,handleInput,handleForm,handleDragStart,handleDragEnd,handleDragOver,handleDrop,openTask,focusProject,focusContext,syncRemote,get delivery(){return local.delivery;},get query(){return local.query;}};
